@Test
public void testBinaryEquals() {
    Expr expr1 = new BinaryOperator(OpType.Plus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    Expr expr2 = new BinaryOperator(OpType.Plus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    assertEquals(expr1, expr2);
    Expr expr3 = new BinaryOperator(OpType.Minus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr3));
    Expr expr4 = new BinaryOperator(OpType.Plus, new LiteralValue("2", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr4));
    Expr expr5 = new BinaryOperator(OpType.Plus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("3", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr5));
}

@Test
public void testBinaryHierarchyEquals() {
    Expr left1 = new BinaryOperator(OpType.Plus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    Expr right1 = new BinaryOperator(OpType.Multiply, new LiteralValue("2", LiteralType.Unsigned_Integer), new LiteralValue("3", LiteralType.Unsigned_Integer));
    Expr one = new BinaryOperator(OpType.Plus, left1, right1);
    Expr left2 = new BinaryOperator(OpType.Plus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    Expr right2 = new BinaryOperator(OpType.Multiply, new LiteralValue("2", LiteralType.Unsigned_Integer), new LiteralValue("3", LiteralType.Unsigned_Integer));
    Expr two = new BinaryOperator(OpType.Plus, left2, right2);
    assertEquals(one, two);
    Expr left3 = new BinaryOperator(OpType.Minus, new LiteralValue("1", LiteralType.Unsigned_Integer), new LiteralValue("2", LiteralType.Unsigned_Integer));
    Expr wrong1 = new BinaryOperator(OpType.Plus, left3, right1);
    assertFalse(one.equals(wrong1));
}

