@Test
public final void testNext() throws IOException, PlanningException {
    FileFragment[] frags = sm.splitNG(conf, "employee", employee.getMeta(), employee.getPath(), Integer.MAX_VALUE);
    Path workDir = new Path(testDir, TestExternalSortExec.class.getName());
    TaskAttemptContext ctx = new TaskAttemptContext(conf, LocalTajoTestingUtility.newQueryUnitAttemptId(), new FileFragment[] { frags[0] }, workDir);
    ctx.setEnforcer(new Enforcer());
    Expr expr = analyzer.parse(QUERIES[0]);
    LogicalPlan plan = planner.createPlan(expr);
    LogicalNode rootNode = plan.getRootBlock().getRoot();
    PhysicalPlanner phyPlanner = new PhysicalPlannerImpl(conf, sm);
    PhysicalExec exec = phyPlanner.createPlan(ctx, rootNode);
    ProjectionExec proj = (ProjectionExec) exec;
    // TODO - should be planed with user's optimization hint
    if (!(proj.getChild() instanceof ExternalSortExec)) {
        UnaryPhysicalExec sortExec = (UnaryPhysicalExec) proj.getChild();
        SeqScanExec scan = (SeqScanExec) sortExec.getChild();
        ExternalSortExec extSort = new ExternalSortExec(ctx, sm, ((MemSortExec) sortExec).getPlan(), scan);
        proj.setChild(extSort);
    }
    Tuple tuple;
    Datum preVal = null;
    Datum curVal;
    int cnt = 0;
    exec.init();
    long start = System.currentTimeMillis();
    while ((tuple = exec.next()) != null) {
        curVal = tuple.get(0);
        if (preVal != null) {
            assertTrue(preVal.lessThanEqual(curVal).asBool());
        }
        preVal = curVal;
        cnt++;
    }
    long end = System.currentTimeMillis();
    exec.close();
    assertEquals(numTuple, cnt);
    // for rescan test
    preVal = null;
    exec.rescan();
    cnt = 0;
    while ((tuple = exec.next()) != null) {
        curVal = tuple.get(0);
        if (preVal != null) {
            assertTrue(preVal.lessThanEqual(curVal).asBool());
        }
        preVal = curVal;
        cnt++;
    }
    assertEquals(numTuple, cnt);
    exec.close();
    System.out.println("Sort Time: " + (end - start) + " msc");
}

