@Test
public void testNextBlock() throws Exception {
    Expr context = analyzer.parse("select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment, ps_supplycost, " + "r_name, p_type, p_size " + "from region join nation on n_regionkey = r_regionkey and r_name = 'AMERICA' " + "join supplier on s_nationkey = n_nationkey " + "join partsupp on s_suppkey = ps_suppkey " + "join part on p_partkey = ps_partkey and p_type like '%BRASS' and p_size = 15");
    LogicalPlan logicalPlan = logicalPlanner.createPlan(context);
    optimizer.optimize(logicalPlan);
    QueryContext queryContext = new QueryContext();
    MasterPlan plan = new MasterPlan(LocalTajoTestingUtility.newQueryId(), queryContext, logicalPlan);
    planner.build(plan);
    ExecutionBlockCursor cursor = new ExecutionBlockCursor(plan);
    int count = 0;
    while (cursor.hasNext()) {
        cursor.nextBlock();
        count++;
    }
    // 5 input relations, 1 broadcast join and 2 symmetric repartition joins and 1 terminal = 8 execution blocks
    assertEquals(8, count);
}

