        assertEquals(0, eachWorker.getUsedMemoryMB());
        assertEquals(0, eachWorker.getUsedDiskSlots(), 0);
        totalUsedMemory += eachWorker.getUsedMemoryMB();
        totalUsedDisks += eachWorker.getUsedDiskSlots();
    }
}

