    Tuple tuple1 = new VTuple(5);
    Tuple tuple2 = new VTuple(5);
    tuple1.put(new Datum[] { DatumFactory.createInt4(9), DatumFactory.createInt4(3), DatumFactory.createInt4(33), DatumFactory.createInt4(4), DatumFactory.createText("abc") });
    tuple2.put(new Datum[] { DatumFactory.createInt4(1), DatumFactory.createInt4(25), DatumFactory.createInt4(109), DatumFactory.createInt4(4), DatumFactory.createText("abd") });
    SortSpec sortKey1 = new SortSpec(schema.getColumnByFQN("col4"), true, false);
    SortSpec sortKey2 = new SortSpec(schema.getColumnByFQN("col5"), true, false);
    TupleComparator tc = new TupleComparator(schema, new SortSpec[] { sortKey1, sortKey2 });
    assertEquals(-1, tc.compare(tuple1, tuple2));
    assertEquals(1, tc.compare(tuple2, tuple1));
}

@Test
public void testContain() {
    VTuple t1 = new VTuple(260);
